import{x as o,o as a,c as l,a9 as e}from"./chunks/framework.DxG24V0C.js";const p=JSON.parse('{"title":"Skill 到底为什么有效，又在哪失效——Demystifying Agent Skills 论文解读","description":"","frontmatter":{"title":"Skill 到底为什么有效，又在哪失效——Demystifying Agent Skills 论文解读"},"headers":[],"relativePath":"reading/01-skill-paper.md","filePath":"reading/01-skill-paper.md","lastUpdated":1788319991000}'),r={name:"reading/01-skill-paper.md"};function i(d,t,n,s,h,u){return a(),l("div",null,[...t[0]||(t[0]=[e('<h1 id="skill-到底为什么有效-又在哪失效" tabindex="-1">Skill 到底为什么有效，又在哪失效 <a class="header-anchor" href="#skill-到底为什么有效-又在哪失效" aria-label="Permalink to &quot;Skill 到底为什么有效，又在哪失效&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">论文信息</p><ul><li><strong>论文</strong>：<a href="https://arxiv.org/abs/2608.14036" target="_blank" rel="noreferrer">《Demystifying Agent Skills: Why They Work—Until They Don&#39;t》</a></li><li><strong>机构</strong>：Princeton / UCSD / Stanford / USC / Johns Hopkins</li><li><strong>版本</strong>：arXiv:2608.14036v1，2026 年 8 月预印本</li><li><strong>阅读时长</strong>：约 20 分钟</li><li><strong>前置知识</strong>：SKILL.md / workflow memory 概念、Agent 主循环、RAG / 记忆检索</li></ul></div><h2 id="一、为什么-skill-的评判要不止看成功率" tabindex="-1">一、为什么 skill 的评判要不止看成功率 <a class="header-anchor" href="#一、为什么-skill-的评判要不止看成功率" aria-label="Permalink to &quot;一、为什么 skill 的评判要不止看成功率&quot;">​</a></h2><p>逐个任务加个 skill、跑一下、看成功率高不高，是评估 skill 价值最常用的方式。这个做法存在一个通行已久的痛点：它只能回答&quot;有没有用&quot;，说不清它在哪一步有效、什么时候反而有害。</p><p>同一个 skill 能成全一个任务，却可能在另一个任务上适得其反。缺了机制层面的理解，&quot;怎么写好 skill&quot;就只能靠玄学式反复调参，这正是 skill 概念长期被视为黑盒的根源。</p><p>论文借此换了个问法：与其问 &quot;whether a skill works&quot;，不如问 &quot;when / why / where a skill works&quot;。前者是给 skill 打分，后者是给 skill 建生命周期，答案落在&quot;什么条件下有效&quot;。</p><p>这也正和本站源码专栏互补：源码能讲清 skill 怎么挂载、怎么注入、怎么检索，&quot;该不该写这一层、什么情况下才管用&quot;则由这篇论文来答。</p><h2 id="二、论文怎么证明" tabindex="-1">二、论文怎么证明 <a class="header-anchor" href="#二、论文怎么证明" aria-label="Permalink to &quot;二、论文怎么证明&quot;">​</a></h2><p>要回答&quot;skill 为什么有效&quot;，首要问题是把&quot;skill 改变了 agent&quot;变成可观测的证据。论文的做法分几步：拆管线、成对轨迹分析、四组受控实验加人工验证。</p><p>skill 的使用被拆成一条生命周期管线：表示 representation → 检索 retrieval → 调用 invocation → 跨框架迁移 transfer，每个环节单独隔离验证。</p><table tabindex="0"><thead><tr><th>RQ</th><th>问什么</th><th>怎么隔离</th></tr></thead><tbody><tr><td>RQ1</td><td>同一轨迹，塞 workflow memory 还是蒸馏成 skill 有没有差别</td><td>只改表示形式</td></tr><tr><td>RQ2</td><td>成败标注显式与否，作用多大</td><td>拿掉标注（no-hint）</td></tr><tr><td>RQ3</td><td>跨框架迁移：Codex 生成、跑在 Gemini CLI</td><td>换执行框架</td></tr><tr><td>RQ4</td><td>检索难度：pool size 5→100、distractor 随机/相似/不相似</td><td>控制候选池</td></tr></tbody></table><p>数据侧，论文把 8135 条 trial 记录归一化，对 240 条采样轨迹做开编码，得到 238 条有效标签，归成 3 大类（SC1 成功 / SC2 执行层失败 / SC3 调用边界失败）、12 种模式。</p><p>人工验证相当扎实：238 个标签各配 3 条轨迹，共 714 次检查；聚合映射与 LLM 一致性 95.8%、Cohen&#39;s κ=0.952，分类并非单模型自说自话。</p><p>实验用两套 agent–model 配对：Codex + GPT-5.3-Codex、Gemini CLI + Gemini-3.1-Pro-Preview；RQ4 因模型可用性改用 Codex + GPT-5.4，只能做同配对内部比较。</p><p>benchmark 包括 Terminal-Bench 2.0（89 任务）、Terminal-Bench Pro（200/8 域）、SkillsBench（86 任务/11 域，带原生 task–skill 标注）。skill 放置遵循 Anthropic 规范，放执行环境作可复用资源，而非内联初始上下文。</p><h2 id="三、核心发现" tabindex="-1">三、核心发现 <a class="header-anchor" href="#三、核心发现" aria-label="Permalink to &quot;三、核心发现&quot;">​</a></h2><h3 id="_3-1-过程锚-vs-知识注入" tabindex="-1">3.1 过程锚 vs 知识注入 <a class="header-anchor" href="#_3-1-过程锚-vs-知识注入" aria-label="Permalink to &quot;3.1 过程锚 vs 知识注入&quot;">​</a></h3><p>skill 整体成功率为 <strong>61.9%</strong>，基线 raw 59.1%、workflow memory 55.9%（后者反而略低于 raw）。skill 相对 workflow 高 <strong>6.06pp</strong>（bootstrap 95% CI [+0.76, +11.36]）。</p><p>因为 workflow 与 skill 出自同一份源轨迹，这差距只能归因于&quot;表示形式&quot;，而非&quot;给了更多经验&quot;——这是全文最有解释力的一组对比。</p><p>机制标签直接揭了底牌：<strong>procedural_anchor（过程锚）占 65.7%</strong>，而 <strong>knowledge_injection（知识注入）仅 4.5%</strong>。结论明确：skill 主要在稳定动作，而非注入知识。</p><p>它稳定的是&quot;跑哪些 setup、走哪条工具序列、做什么中间验证、避开哪个坑&quot;，把&quot;其实会做的流程&quot;回构成不跑偏的标准动作。综上，skill 降低的是流程的过程不确定性，不是知识的稀缺性。</p><h3 id="_3-2-它修执行层失败-不修算法与推理" tabindex="-1">3.2 它修执行层失败，不修算法与推理 <a class="header-anchor" href="#_3-2-它修执行层失败-不修算法与推理" aria-label="Permalink to &quot;3.2 它修执行层失败，不修算法与推理&quot;">​</a></h3><p>把 12 种 mode 归到三类后，&quot;skill 修什么、不修什么&quot;排得很清楚。最显著的是 <strong>SC2 执行层失败：raw 37.3% → skill 23.5%</strong>。</p><table tabindex="0"><thead><tr><th>失败模式</th><th>Raw</th><th>Workflow</th><th>Skill</th></tr></thead><tbody><tr><td>环境基础设施失败</td><td>5.3%</td><td>1.7%</td><td>0.2%</td></tr><tr><td>输出格式 / schema 不符</td><td>7.4%</td><td>3.8%</td><td>3.2%</td></tr><tr><td>后台服务生命周期失败</td><td>2.7%</td><td>2.5%</td><td>0.8%</td></tr><tr><td>Shell 命令交付</td><td>1.1%</td><td>1.9%</td><td>0.2%</td></tr></tbody></table><p>这些都是&quot;更可被编码&quot;的失败：setup 顺序、依赖 workaround、路径约定，一经发现就能固定进 skill，收益立竿见影。</p><p>边界同样清楚：算法逻辑错误从 raw 8.3% 到 skill 7.4%，静态验证不使用运行时则从 12.5% → 12.5% → 11.7%。skill 不自动帮 agent 重想算法，也不强制对齐 oracle 验证，提升的是执行健壮性，不是问题重构能力。</p><h3 id="_3-3-skill-也引入新的失败面" tabindex="-1">3.3 skill 也引入新的失败面 <a class="header-anchor" href="#_3-3-skill-也引入新的失败面" aria-label="Permalink to &quot;3.3 skill 也引入新的失败面&quot;">​</a></h3><p>抽象既是优势，也会带来新失败：skill_guidance_misapplied_or_ignored 占 <strong>10.0%</strong>（raw 0.8%、workflow 0.4%），agent 拿着看似合理的 skill 机械套用、错认前提、配上不成立的假设。</p><p>workflow 的软肋则是 timeout_budget_exhaustion <strong>10.6%</strong>（raw 1.7%），因为原始轨迹留下的探索分支与噪音太多。skill 的一次失败，往往不是内容写错，而是 agent 判断错&quot;此刻该不该由 skill 主事&quot;。</p><h3 id="_3-4-outcome-标注的作用" tabindex="-1">3.4 outcome 标注的作用 <a class="header-anchor" href="#_3-4-outcome-标注的作用" aria-label="Permalink to &quot;3.4 outcome 标注的作用&quot;">​</a></h3><p>no-hint 消融给出反直觉结论：只喂成功样本时，加不加成败标注差别不大；一旦混入失败轨迹就拉开距离。典型例子 Gemini 在 TB2 的 3s2f 任务：normal 0.7462 vs no-hint 0.4000。</p><p>工程启示：写 skill 时，失败样本的&quot;可识别性&quot;最可贵，它教 agent&quot;该避什么、踩坑怎么爬出来&quot;；没有失败样本，防御性知识便无从谈起。</p><h3 id="_3-5-检索是独立瓶颈" tabindex="-1">3.5 检索是独立瓶颈 <a class="header-anchor" href="#_3-5-检索是独立瓶颈" aria-label="Permalink to &quot;3.5 检索是独立瓶颈&quot;">​</a></h3><p>RQ4 用同一候选池（真 skill + k−1 个 distractor）跑三套评测，pool 从 5 增到 100：</p><table tabindex="0"><thead><tr><th>指标</th><th>k=5 → k=100</th></tr></thead><tbody><tr><td>实际使用的 precision</td><td>29.6% → 3.3%</td></tr><tr><td>下游成功率</td><td>36.4% → 39.3%</td></tr><tr><td>Embedding top-1 precision</td><td>88.3% → 76.9%</td></tr><tr><td>Agent 显式选择 precision</td><td>70.0% → 63.7%</td></tr></tbody></table><p>三个教训都击碎&quot;精确命中等于成功&quot;的直觉：pool 越大实际 use precision 崩到 3.3%，但下游成功率几乎持平；相似 distractor 压力最大（embedding top-1 从 70.5 掉到 53.4），但 k=100 的 recall 仍达 54.3–73.6%；精确 ground-truth 调用既不充分也不必要，相关而非 ground-truth 的 skill 也能提供程序性支撑。</p><h2 id="四、对本站读者与-skill-md-写法的启发" tabindex="-1">四、对本站读者与 SKILL.md 写法的启发 <a class="header-anchor" href="#四、对本站读者与-skill-md-写法的启发" aria-label="Permalink to &quot;四、对本站读者与 SKILL.md 写法的启发&quot;">​</a></h2><p>结合源码专栏，给三条可落地的经验：</p><h3 id="_4-1-少堆知识-多堆步骤" tabindex="-1">4.1 少堆知识，多堆步骤 <a class="header-anchor" href="#_4-1-少堆知识-多堆步骤" aria-label="Permalink to &quot;4.1 少堆知识，多堆步骤&quot;">​</a></h3><p>论文 65.7% 的 label 在稳定动作而非注入知识。最有价值的是可执行步骤、验证清单、常见坑，而不是业务背景解释。想&quot;什么能让流程不易跑偏&quot;，就从那写起。</p><h3 id="_4-2-多写-avoidance-该避的坑" tabindex="-1">4.2 多写 avoidance（该避的坑） <a class="header-anchor" href="#_4-2-多写-avoidance-该避的坑" aria-label="Permalink to &quot;4.2 多写 avoidance（该避的坑）&quot;">​</a></h3><p>no-hint 实验说明，价值最贵的是失败经验里的防御性知识。优先把&quot;曾经踩过的具体坑&quot;写进 skill，它只能从失败里长出来——这也是失败样本显得珍贵的原因。</p><h3 id="_4-3-检索大库要特别设计" tabindex="-1">4.3 检索大库要特别设计 <a class="header-anchor" href="#_4-3-检索大库要特别设计" aria-label="Permalink to &quot;4.3 检索大库要特别设计&quot;">​</a></h3><p>RQ4 提示：库越大、skill 越相近，自动检索越难命中。库大时别只靠 description 检索，配合召回策略、命名收敛、显式规则一起设计，否则真实命中率会让人失望。</p><h2 id="五、局限速写" tabindex="-1">五、局限速写 <a class="header-anchor" href="#五、局限速写" aria-label="Permalink to &quot;五、局限速写&quot;">​</a></h2><ul><li>只测了终端/工具型任务（Terminal-Bench / SkillsBench），不含 web 或开环协作，别类任务结论要额外验证</li><li>agent–model 只有两套，RQ4 换了 Codex + GPT-5.4，只能做同配对内部比较</li><li>taxonomy 来自约 3% 的抽样轨迹，低频失败模式未必覆盖完全</li></ul><h2 id="六、深度理解问答" tabindex="-1">六、深度理解问答 <a class="header-anchor" href="#六、深度理解问答" aria-label="Permalink to &quot;六、深度理解问答&quot;">​</a></h2><h3 id="q1-为什么-技能检索到-不等于-任务成功" tabindex="-1">Q1 为什么&quot;技能检索到&quot;不等于&quot;任务成功&quot; <a class="header-anchor" href="#q1-为什么-技能检索到-不等于-任务成功" aria-label="Permalink to &quot;Q1 为什么&quot;技能检索到&quot;不等于&quot;任务成功&quot;&quot;">​</a></h3><p>因为&quot;找到正确 skill&quot;与&quot;把它执行到位&quot;是两步独立能力。RQ4 里最直观的反差：实际 use precision 崩到 3.3%，下游成功率却升到 39.3%。agent 可能在干扰中选中了却在错误 context，也可能选了相关但非 ground-truth 的那份却照样成事。命中是必要前提，但不是充分条件。</p><h3 id="q2-那是不是该把-workflow-memory-全砍掉" tabindex="-1">Q2 那是不是该把 workflow memory 全砍掉 <a class="header-anchor" href="#q2-那是不是该把-workflow-memory-全砍掉" aria-label="Permalink to &quot;Q2 那是不是该把 workflow memory 全砍掉&quot;">​</a></h3><p>不该二取一。两者是替换方案，取舍如下：workflow memory token 最省（83 任务交集比 raw 少 129.5K token）；skill 成功率最高（比 raw +5.5pp），但每任务多花约 95.3K token，且更强制的表示。strings 上省 token 的进 workflow，需要稳定动作的写成 skill。</p><h3 id="q3-为什么失败样本那么关键" tabindex="-1">Q3 为什么失败样本那么关键 <a class="header-anchor" href="#q3-为什么失败样本那么关键" aria-label="Permalink to &quot;Q3 为什么失败样本那么关键&quot;">​</a></h3><p>因为&quot;避免踩坑&quot;的价值主要藏在失败样本里。只喂成功轨迹时，成败标签可有可无；一旦混入失败样本又被拿掉标签，skill 的防御半径就塌掉了。原因在于 skill 里最值钱的防御性内容，只能从失败里长出来。</p><h3 id="q4-与源码专栏如何互补" tabindex="-1">Q4 与源码专栏如何互补 <a class="header-anchor" href="#q4-与源码专栏如何互补" aria-label="Permalink to &quot;Q4 与源码专栏如何互补&quot;">​</a></h3><p>源码专栏解释 skill &quot;怎么实现&quot;（怎么挂载、怎么注入、怎么检索），本篇论文给定&quot;什么值得被写成 skill&quot;（稳定流程、避开坑、检索抗混淆）。源码讲机制，论文讲价值与边界，两者叠加才能判断一份 SKILL.md 写得好不好。</p><h2 id="七、结论" tabindex="-1">七、结论 <a class="header-anchor" href="#七、结论" aria-label="Permalink to &quot;七、结论&quot;">​</a></h2><p>一句打包，但拆成三句：<strong>skill 是过程锚，不是知识库</strong>——稳定的是动作而非补充知识，6.06pp 来自表示形态而非多次训练；<strong>检索是独立瓶颈</strong>——命中与成功松耦合，池越大越相似越难，精确 ground-truth 既不充分也不必要；<strong>失效来自边界</strong>——修执行层而不修算法推理，且会带来误用，关键不在&quot;写没写&quot;而在&quot;何时用、用哪个、怎么适配&quot;。</p><hr><blockquote><p>本篇为<strong>论文解读</strong>，与本站源码专栏互为补充。数据均取自论文正文与附录 A 各表（表 1/2/3/11/15/16），无杜撰。</p></blockquote>',59)])])}const q=o(r,[["render",i]]);export{p as __pageData,q as default};
